# name: terminal_run_choice_rate
# description: Among pairs whose sequences differ in the length of the run at their end (final streak), the proportion of choices of the sequence with the longer final run; observed < null means people penalise streaks at the end of a sequence (recency) more than the model's position-blind longest-run term predicts.
def test_statistic(df):
    def trun(s):
        s = str(s); k = 1
        while k < len(s) and s[-k-1] == s[-1]:
            k += 1
        return k
    ua = df["sequence_a"].map({u: trun(u) for u in df["sequence_a"].unique()})
    ub = df["sequence_b"].map({u: trun(u) for u in df["sequence_b"].unique()})
    m = (ua != ub).values
    if m.sum() == 0:
        return 0.5
    c = df["chose_left"].values[m]
    left_longer = (ua > ub).values[m]
    return float(np.mean(np.where(left_longer, c, 1 - c)))

# name: distinct_triplet_choice_rate
# description: Among pairs whose sequences differ in the number of distinct length-3 substrings (motif variety), the proportion of choices of the sequence with more distinct triplets; observed > null means people favour pattern variety / incompressibility beyond what alternation, balance and longest-run terms produce.
def test_statistic(df):
    def ntrip(s):
        s = str(s)
        return len({s[i:i+3] for i in range(len(s) - 2)})
    ua = df["sequence_a"].map({u: ntrip(u) for u in df["sequence_a"].unique()})
    ub = df["sequence_b"].map({u: ntrip(u) for u in df["sequence_b"].unique()})
    m = (ua != ub).values
    if m.sum() == 0:
        return 0.5
    c = df["chose_left"].values[m]
    left_more = (ua > ub).values[m]
    return float(np.mean(np.where(left_more, c, 1 - c)))

# name: perfect_alternation_choice_rate
# description: Among pairs where exactly one sequence is perfectly alternating (HTHT.../THTH...), the proportion of choices of that perfectly alternating sequence; observed < null means people reject perfect alternation as too regular more than the model's smooth ideal-alternation curve predicts (observed > null the reverse).
def test_statistic(df):
    def isalt(s):
        return (s.str.contains("HH") | s.str.contains("TT")) == False
    a = isalt(df["sequence_a"]) & (df["sequence_a"].str.len() >= 3)
    b = isalt(df["sequence_b"]) & (df["sequence_b"].str.len() >= 3)
    m = a != b
    if m.sum() == 0:
        return 0.5
    chose_alt = np.where(a[m], df["chose_left"][m], 1 - df["chose_left"][m])
    return float(np.mean(chose_alt))

# name: left_rate_participant_sd
# description: SD across participants of each person's proportion of Left responses; observed > null means people have personal side biases the model (no side term) underproduces.
def test_statistic(df):
    return float(df.groupby("participant_id")["chose_left"].mean().std(ddof=0))

# name: short_length_alternation_preference
# description: Proportion choosing the sequence with more alternations among pairs of length <= 7 minus the same among length-8 pairs (unequal alternation counts only); observed != null means sensitivity to alternation depends on sequence length in a way the model's length-normalised rate terms miss (observed < null: weaker preference on short sequences than predicted).
def test_statistic(df):
    def nalt(s):
        s = str(s)
        return sum(1 for x, y in zip(s, s[1:]) if x != y)
    ua = df["sequence_a"].map({u: nalt(u) for u in df["sequence_a"].unique()}).values
    ub = df["sequence_b"].map({u: nalt(u) for u in df["sequence_b"].unique()}).values
    L = df["sequence_a"].str.len().values
    m = ua != ub
    c = df["chose_left"].values
    chose_more = np.where(ua > ub, c, 1 - c)
    s = m & (L <= 7); l = m & (L == 8)
    if s.sum() == 0 or l.sum() == 0:
        return 0.0
    return float(chose_more[s].mean() - chose_more[l].mean())
